// Node: Verificar tudo  (Code, "Run Once for All Items")
// Roda a cada 5 minutos. Confere Evolution/WhatsApp, Ollama, Whisper e Piper.
// Só envia e-mail quando há mudança (caiu, voltou) ou um lembrete a cada 1 hora.

// ================== CONFIGURE AQUI ==================
const EVOLUTION_URL = "http://localhost:8080";
const EVOLUTION_APIKEY = "COLE_AQUI_A_CHAVE_DA_EVOLUTION";   // a mesma usada nos nós "Enviar..."
const INSTANCIA = "GasBot";
const OLLAMA_URL = "http://localhost:11434";
const WHISPER_URL = "http://localhost:9000";
const PIPER_URL = "http://localhost:5051";

const FALHAS_PARA_AVISAR = 2;   // verificações seguidas com problema antes de avisar (2 x 5 min = 10 min)
const LEMBRETE_MINUTOS = 60;    // se o problema continuar, lembra a cada 60 min
const REINICIO_MINUTOS = 15;    // tenta reiniciar a instância no máximo a cada 15 min
const FORCAR_TESTE = false;     // true = manda um e-mail de teste agora (volte para false depois)
// =====================================================

const req = (opcoes) => this.helpers.httpRequest(opcoes);

// Qualquer resposta do serviço (mesmo erro 404) quer dizer que ele está no ar.
async function consultar(url, headers) {
  try {
    const corpo = await req({ method: "GET", url, headers: headers || {}, timeout: 8000, json: true });
    return { ok: true, corpo };
  } catch (e) {
    const codigo = Number(e.httpCode || e.statusCode || (e.response && e.response.status) || 0);

    if (codigo) {
      return { ok: true, corpo: null, codigo };
    }

    return { ok: false, erro: String((e && e.message) || e).slice(0, 100) };
  }
}

const [evo, ollama, whisper, piper] = await Promise.all([
  consultar(`${EVOLUTION_URL}/instance/connectionState/${INSTANCIA}`, { apikey: EVOLUTION_APIKEY }),
  consultar(`${OLLAMA_URL}/api/tags`),
  consultar(`${WHISPER_URL}/docs`),
  consultar(`${PIPER_URL}/`)
]);

const problemas = {};
let estadoWhatsapp = "";

const NOME_EVO = "Evolution API";
const NOME_ZAP = `WhatsApp (instância ${INSTANCIA})`;

if (!evo.ok) {
  problemas[NOME_EVO] = `não responde (${evo.erro})`;
} else {
  estadoWhatsapp = String((evo.corpo && ((evo.corpo.instance && evo.corpo.instance.state) || evo.corpo.state)) || "");

  if (!evo.corpo) {
    problemas[NOME_EVO] = `respondeu com erro HTTP ${evo.codigo} (confira a chave da Evolution)`;
  } else if (estadoWhatsapp !== "open") {
    problemas[NOME_ZAP] = `desconectado (estado: ${estadoWhatsapp || "desconhecido"})`;
  }
}

if (!ollama.ok) problemas["Ollama (IA)"] = `não responde (${ollama.erro})`;
if (!whisper.ok) problemas["Whisper (áudio para texto)"] = `não responde (${whisper.erro})`;
if (!piper.ok) problemas["Piper (voz)"] = `não responde (${piper.erro})`;

// ---------- memória entre as execuções ----------
const agora = Date.now();
const sd = $getWorkflowStaticData("global");
sd.vigia = sd.vigia || { falhas: {}, avisados: {}, ultimoLembrete: 0, ultimoReinicio: 0 };
const v = sd.vigia;

const voltaram = [];

for (const nome of Object.keys(v.falhas)) {
  if (!problemas[nome]) {
    if (v.avisados[nome]) voltaram.push(nome);
    delete v.falhas[nome];
    delete v.avisados[nome];
  }
}

const nomes = Object.keys(problemas);

for (const nome of nomes) {
  v.falhas[nome] = (v.falhas[nome] || 0) + 1;
}

const novos = nomes.filter(n => v.falhas[n] >= FALHAS_PARA_AVISAR && !v.avisados[n]);
const emAberto = nomes.filter(n => v.avisados[n]);
const lembrar = novos.length === 0 && emAberto.length > 0 && (agora - v.ultimoLembrete) > LEMBRETE_MINUTOS * 60000;

// ---------- tentativa de reinício da conexão do WhatsApp ----------
let reinicio = "";

if (
  problemas[NOME_ZAP] &&
  v.falhas[NOME_ZAP] >= FALHAS_PARA_AVISAR &&
  ["connecting", "close"].includes(estadoWhatsapp) &&
  (agora - v.ultimoReinicio) > REINICIO_MINUTOS * 60000
) {
  v.ultimoReinicio = agora;

  try {
    await req({
      method: "PUT",
      url: `${EVOLUTION_URL}/instance/restart/${INSTANCIA}`,
      headers: { apikey: EVOLUTION_APIKEY },
      timeout: 15000
    });
    reinicio = "Tentei reiniciar a instância automaticamente.";
  } catch (e) {
    reinicio = "Tentei reiniciar a instância, mas não consegui.";
  }
}

// ---------- monta o e-mail (ou não envia nada) ----------
const hora = new Date().toLocaleString("pt-BR", { timeZone: "America/Sao_Paulo" });
const linhas = (lista, usarProblema) => lista.map(n => `• ${n}${usarProblema ? ": " + problemas[n] : ""}`).join("\n");

function dicasPara(lista) {
  const dicas = [];

  if (lista.includes(NOME_ZAP)) {
    dicas.push("• WhatsApp desconectado: abra http://localhost:8080/manager, entre na instância e clique em Connect (leia o QR Code se ele pedir).");
  }

  if (lista.some(n => n !== NOME_ZAP)) {
    dicas.push("• Serviço que não responde: rode 'docker ps' e veja se o container está ligado. Se estiver parado, use 'docker start nome_do_container'. O Ollama é um programa do Windows: confira se está aberto.");
  }

  dicas.push("• Se o computador acabou de voltar da suspensão: rode 'wsl --shutdown' no PowerShell e abra o Docker Desktop de novo.");

  return dicas.join("\n");
}

let assunto = "";
let texto = "";

if (FORCAR_TESTE) {
  assunto = "[GasBot] Teste do vigia";
  texto =
    `Teste feito em ${hora}.\n\n` +
    (nomes.length ? `Problemas agora:\n${linhas(nomes, true)}` : "Tudo funcionando: Evolution, WhatsApp, Ollama, Whisper e Piper.");
} else if (novos.length) {
  novos.forEach(n => { v.avisados[n] = true; });
  v.ultimoLembrete = agora;

  assunto = `[GasBot] PROBLEMA: ${novos.join(", ")}`;
  texto =
    `Detectado em ${hora}.\n\n${linhas(novos, true)}\n\n` +
    (reinicio ? reinicio + "\n\n" : "") +
    "O que fazer:\n" +
    dicasPara(novos) + "\n\n" +
    (voltaram.length ? `Já voltaram ao normal:\n${linhas(voltaram, false)}\n\n` : "") +
    (emAberto.length ? `Ainda com problema desde antes:\n${linhas(emAberto, true)}` : "");
} else if (voltaram.length) {
  assunto = `[GasBot] Voltou ao normal: ${voltaram.join(", ")}`;
  texto =
    `Verificado em ${hora}.\n\n${linhas(voltaram, false)}\n\n` +
    (emAberto.length ? `Ainda com problema:\n${linhas(emAberto, true)}` : "Está tudo funcionando de novo.");
} else if (lembrar) {
  v.ultimoLembrete = agora;
  assunto = `[GasBot] Lembrete: continua com problema`;
  texto = `Verificado em ${hora}.\n\n${linhas(emAberto, true)}`;
}

if (!assunto) {
  return [];
}

return [{ json: { assunto, texto } }];
